const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and time
  const lon = 86.428836;
  const lat = 35.879797;
  const point = ee.Geometry.Point([lon, lat]);
  const buffer = point.buffer(50000); // 50 km radius in meters

  const startDate = '2024-08-11';
  const endDate = '2024-08-12';

  // 2. Acquire Sentinel-2 data
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const imgCount = await col.size().getInfo();
  console.log(`Sentinel-2 Images found: ${imgCount}`);

  if (imgCount === 0) {
    // Fallback: try Landsat 8
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    const imgCount2 = await col.size().getInfo();
    console.log(`Landsat-8 Images found: ${imgCount2}`);

    if (imgCount2 === 0) {
      console.log('No imagery available for Aug 11, 2024');
      console.log('C1');
      return;
    }
  }

  // 3. Use first available image for water detection
  const img = col.first();

  // Calculate NDWI (Normalized Difference Water Index)
  // NDWI = (Green - NIR) / (Green + NIR)
  // For Sentinel-2: B3 (Green), B8 (NIR)
  const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');

  // Detect water (NDWI > 0.3 indicates water)
  const water = ndwi.gt(0.3);

  // 4. Count connected components (lakes/water bodies)
  // Mask water pixels
  const waterMasked = water.updateMask(water);

  // Count valid water pixels
  const pixelCount = waterMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 10,
    maxPixels: 1e9
  });

  const validPixels = await pixelCount.get('NDWI').getInfo();
  console.log(`Valid water pixels: ${validPixels}`);

  if (validPixels === null || validPixels === 0) {
    console.log('No valid water pixels detected');
    console.log('C2');
    return;
  }

  // 5. Identify individual lakes using connected components
  const connected = water.connectedComponents(ee.Kernel.plus(1), 256);
  const labeledWater = connected.updateMask(water);

  // Count number of unique lake objects
  const uniqueLakes = labeledWater.reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: buffer,
    scale: 10,
    maxPixels: 1e9
  });

  const lakeCount = await uniqueLakes.get('labels').getInfo();
  console.log(`Number of lakes detected: ${lakeCount}`);

  if (lakeCount === null || lakeCount === undefined) {
    console.log('Calculation failed');
    console.log('C3');
    return;
  }

  // 6. Determine answer
  if (lakeCount > 3) {
    console.log(`Result: ${lakeCount} lakes > 3`);
    console.log('A');
  } else {
    console.log(`Result: ${lakeCount} lakes <= 3`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
